<?php
declare(strict_types=1); require_once __DIR__.'/auth.php'; require_login(); $pdo=db(); if(!table_exists($pdo,'invoices')) redirect('upgrade_phase2.php'); $msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=post_int('client_id');$amount=(float)($_POST['amount']??0);$desc=post_string('description');if($client&&$amount>0&&$desc!==''){try{$pdo->beginTransaction();$num='INV-'.date('YmdHis').'-'.random_int(100,999);$st=$pdo->prepare('INSERT INTO invoices(client_id,invoice_number,status,issue_date,due_date,subtotal,total_amount) VALUES(?,?,?,?,?,?,?)');$st->execute([$client,$num,'draft',date('Y-m-d'),post_string('due_date')?:null,$amount,$amount]);$iid=(int)$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,line_total) VALUES(?,?,1,?,?)');$st->execute([$iid,$desc,$amount,$amount]);$pdo->commit();activity($pdo,'create','invoices',$iid,'Invoice created: '.$num);flash('success','Invoice created.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[SPS INVOICE] '.$e->getMessage());flash('success','Invoice could not be created.');}}else{flash('success','Client, description and positive amount are required.');}redirect('invoices.php');}
$clients=$pdo->query("SELECT id,first_name,last_name FROM clients WHERE deleted_at IS NULL ORDER BY last_name")->fetchAll();$rows=$pdo->query("SELECT i.*,CONCAT(c.first_name,' ',c.last_name) client_name FROM invoices i JOIN clients c ON c.id=i.client_id ORDER BY i.id DESC LIMIT 200")->fetchAll();$total=(float)$pdo->query("SELECT COALESCE(SUM(total_amount-paid_amount),0) FROM invoices WHERE status NOT IN ('paid','cancelled')")->fetchColumn();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoices · SPS CRM</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 2fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:11px 14px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.total{font-size:28px;font-weight:850}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:820px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Invoices</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="card" style="margin-bottom:16px"><div>Outstanding Balance</div><div class="total">$<?=money($total)?></div></div><div class="grid"><div class="card"><h2>Create Invoice</h2><form method="post"><?=csrf_field()?><div class="field"><label>Client</label><select name="client_id" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Description</label><input name="description" required></div><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Due date</label><input name="due_date" type="date"></div><button class="btn">Create Draft Invoice</button></form></div><div class="card"><h2>Invoices</h2><table class="table"><tr><th>Number</th><th>Client</th><th>Status</th><th>Total</th><th>Paid</th><th>Due</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['invoice_number'])?></td><td><?=e($r['client_name'])?></td><td><?=e($r['status'])?></td><td>$<?=money($r['total_amount'])?></td><td>$<?=money($r['paid_amount'])?></td><td><?=e($r['due_date']?:'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No invoices yet.</td></tr><?php endif;?></table></div></div></main></body></html>
